package com.devopsclassroom.entity;
import com.fasterxml.jackson.annotation.JsonIgnore; import jakarta.persistence.*;
@Entity @Table(name="equipes") public class Equipe { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false,length=120) private String nome; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="turma_id",nullable=false) @JsonIgnore private Turma turma; @ManyToMany(fetch=FetchType.LAZY) @JoinTable(name="equipe_alunos",joinColumns=@JoinColumn(name="equipe_id"),inverseJoinColumns=@JoinColumn(name="aluno_id")) private java.util.Set<Usuario> alunos=new java.util.HashSet<>(); @Lob @Column(name="checklist_json",nullable=false) private String checklistJson="[]"; public Long getId(){return id;} public void setId(Long v){id=v;} public String getNome(){return nome;} public void setNome(String v){nome=v;} public Turma getTurma(){return turma;} public void setTurma(Turma v){turma=v;} public java.util.Set<Usuario> getAlunos(){return alunos;} public void setAlunos(java.util.Set<Usuario> v){alunos=v;} public String getChecklistJson(){return checklistJson;} public void setChecklistJson(String v){checklistJson=v;} }
